def _ancestors(start: Path) -> list[Path]:
    resolved = start.resolve()
    if resolved.is_file():
        resolved = resolved.parent
    return [resolved, *resolved.parents]

def _find_up(start: Path, name: str) -> Path | None:
    for parent in _ancestors(start):
        if (parent / name).exists():
            return parent
    return None

def _resolve_dir(root: Path, value: str) -> Path:
    candidate = Path(value).expanduser()
    if not candidate.is_absolute():
        candidate = root / candidate
    return candidate.resolve()

if explicit:
        root = Path(explicit).expanduser().resolve()
        source: WorkspaceSource = "explicit"
    elif env_root:
        root = Path(env_root).expanduser().resolve()
        source = "env"
    else:
        config_root = _find_up(start_path, "kc.toml")
        if config_root is not None:
            root = config_root
            source = "kc.toml"
        else:
            git_root = _find_up(start_path, ".git")
            if git_root is not None:
                root = git_root
                source = "git"
            else:
                root = start_path if start_path.is_dir() else start_path.parent
                source = "cwd"

def __exit__(self, exc_type: object, exc: object, tb: object) -> None:
        if exc_type is not None:
            self._write_status("failed", details={"exception_type": getattr(exc_type, "__name__", str(exc_type))})
        self._lock.__exit__(exc_type, exc, tb)

def mutation_transaction(paths: KcPaths, command: str, targets: list[Path | str]) -> MutationTransaction:
    return MutationTransaction(
        paths=paths,
        command=command,
        targets=[
            repo_relative(target) if isinstance(target, Path) else str(target)
            for target in targets
        ],
    )

